1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.time.LocalDate;
4	
5	import net.officefloor.plugin.variable.Val;
6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	import org.springframework.samples.petclinic.rest.escalation.FutureRegistrationDateException;
8	
9	/**
10	 * Rejects a supplied registration date later than the server's current date, but only
11	 * WHEN PRESENT: an absent registration date defaults to the server date (see
12	 * {@link BusinessDays}) and is always accepted. An out-of-range future date is rejected
13	 * with 400 through {@link FutureRegistrationDateException}.
14	 */
15	public class ValidateOwnerRegistrationDate {
16	
17	    public void service(@Val OwnerFieldsDto request) throws FutureRegistrationDateException {
18	        LocalDate supplied = request.getRegistrationDate();
19	        if (supplied == null) {
20	            return;
21	        }
22	        LocalDate serverDate = LocalDate.now();
23	        if (supplied.isAfter(serverDate)) {
24	            throw new FutureRegistrationDateException(supplied, serverDate);
25	        }
26	    }
27	}
