1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.time.DayOfWeek;
4	import java.time.LocalDate;
5	
6	import org.springframework.samples.petclinic.repository.OwnerRepository;
7	
8	/**
9	 * Business-day helper for owner registration. A registration date must fall on a
10	 * business day: a Saturday or Sunday rolls forward to the following Monday. Single
11	 * source of truth for the effective registration date and the per-business-day owner
12	 * count, so every caller (the stored value, the daily create-limit and the bulk-signup
13	 * warning) agrees.
14	 */
15	final class BusinessDays {
16	
17	    private BusinessDays() {
18	    }
19	
20	    /**
21	     * Counts the existing owners whose registration date equals {@code businessDay}.
22	     * The single source of truth for "how many owners were created on a business day",
23	     * so per-day rules (the create-limit and the bulk-signup warning) cannot drift
24	     * apart. The caller passes a day already resolved via
25	     * {@link #effectiveRegistrationDate(LocalDate)}.
26	     */
27	    static long countCreatedOn(OwnerRepository ownerRepository, LocalDate businessDay) {
28	        return ownerRepository.findAll().stream()
29	            .filter(existing -> businessDay.equals(existing.getRegistrationDate()))
30	            .count();
31	    }
32	
33	    /**
34	     * The effective registration date: {@code supplied} when present, otherwise the
35	     * server's current date, rolled forward over a weekend to the following Monday.
36	     */
37	    static LocalDate effectiveRegistrationDate(LocalDate supplied) {
38	        return rollToBusinessDay(supplied != null ? supplied : LocalDate.now());
39	    }
40	
41	    /** Rolls {@code date} forward to the next business day: a weekend becomes Monday. */
42	    private static LocalDate rollToBusinessDay(LocalDate date) {
43	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY || date.getDayOfWeek() == DayOfWeek.SUNDAY) {
44	            date = date.plusDays(1);
45	        }
46	        return date;
47	    }
48	}
