1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.time.LocalDate;
4	
5	import net.officefloor.plugin.variable.Val;
6	import org.springframework.samples.petclinic.model.Owner;
7	import org.springframework.samples.petclinic.repository.OwnerRepository;
8	
9	/**
10	 * Assigns the owner's {@code bulkSignupWarning}: {@code true} when more than 80 owners
11	 * have already been created on the new owner's effective business day, otherwise
12	 * {@code false}. The business day is resolved through {@link BusinessDays} (the same
13	 * single source of truth {@link EnsureDailyLimit} uses) and the count comes from
14	 * {@link BusinessDays#countCreatedOn}, so the two per-day rules cannot drift apart. The
15	 * count is over the existing owners (the new owner is not yet saved); the threshold is
16	 * strictly more than 80.
17	 */
18	public class AssessBulkSignup {
19	
20	    private static final int BULK_SIGNUP_THRESHOLD = 80;
21	
22	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
23	        LocalDate businessDay = BusinessDays.effectiveRegistrationDate(owner.getRegistrationDate());
24	        long createdToday = BusinessDays.countCreatedOn(ownerRepository, businessDay);
25	        owner.setBulkSignupWarning(createdToday > BULK_SIGNUP_THRESHOLD);
26	    }
27	}
