1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.time.LocalDate;
4	
5	import net.officefloor.plugin.variable.Val;
6	import org.springframework.samples.petclinic.repository.OwnerRepository;
7	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
8	import org.springframework.samples.petclinic.rest.escalation.DailyLimitExceededException;
9	
10	/**
11	 * Rejects creating an owner when 100 or more owners have already been created on the new
12	 * owner's effective business day. That day is the supplied registration date, or the
13	 * server date when omitted, rolled forward over a weekend to the following Monday — the
14	 * same adjustment {@link BuildOwner} stores — so the count is taken per adjusted business
15	 * day. The count is over the existing owners (the new owner is not yet saved). At 100 or
16	 * more the request is a 429 Too Many Requests (see {@link DailyLimitExceededException}).
17	 */
18	public class EnsureDailyLimit {
19	
20	    private static final int DAILY_LIMIT = 100;
21	
22	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
23	            throws DailyLimitExceededException {
24	        LocalDate businessDay = BusinessDays.effectiveRegistrationDate(request.getRegistrationDate());
25	        long createdToday = BusinessDays.countCreatedOn(ownerRepository, businessDay);
26	        if (createdToday >= DAILY_LIMIT) {
27	            throw new DailyLimitExceededException(createdToday);
28	        }
29	    }
30	}
