27	/**
28	 * Simple JavaBean domain object representing an owner.
29	 *
30	 * @author Ken Krebs
31	 * @author Juergen Hoeller
32	 * @author Sam Brannen
33	 * @author Michael Isvy
34	 */
35	@Entity
36	@Table(name = "owners")
37	public class Owner extends Person {
38	    @Column(name = "address")
39	    @NotEmpty
40	    private String address;
41	
42	    @Column(name = "city")
43	    @NotEmpty
44	    private String city;
45	
46	    @Column(name = "telephone")
47	    @NotEmpty
48	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 format")
49	    private String telephone;
50	
51	    @Column(name = "email")
52	    private String email;
53	
54	    @Column(name = "registration_date", columnDefinition = "DATE")
55	    private LocalDate registrationDate;
56	
57	    @Column(name = "customer_code")
58	    private String customerCode;
59	
60	    @Column(name = "household_id")
61	    private String householdId;
62	
63	    @Column(name = "namesake_count")
64	    private Integer namesakeCount;
65	
66	    @Column(name = "bulk_signup_warning")
67	    private Boolean bulkSignupWarning;
68	
69	    @Column(name = "postcode")
70	    private String postcode;
71	
72	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
73	    private Set<Pet> pets;
74	
75	    public String getAddress() {
76	        return this.address;
77	    }
78	
79	    public void setAddress(String address) {
80	        this.address = address;
81	    }
82	
83	    public String getCity() {
84	        return this.city;
85	    }
86	
87	    public void setCity(String city) {
88	        this.city = city;
89	    }
90	
91	    public String getTelephone() {
92	        return this.telephone;
93	    }
94	
95	    public void setTelephone(String telephone) {
96	        this.telephone = telephone;
97	    }
98	
99	    public String getEmail() {
100	        return this.email;
101	    }
102	
103	    public void setEmail(String email) {
104	        this.email = email;
105	    }
106	
107	    public LocalDate getRegistrationDate() {
108	        return this.registrationDate;
109	    }
110	
111	    public void setRegistrationDate(LocalDate registrationDate) {
112	        this.registrationDate = registrationDate;
113	    }
114	
115	    public String getCustomerCode() {
116	        return this.customerCode;
117	    }
118	
119	    public void setCustomerCode(String customerCode) {
120	        this.customerCode = customerCode;
121	    }
122	
123	    public String getHouseholdId() {
124	        return this.householdId;
125	    }
126	
127	    public void setHouseholdId(String householdId) {
128	        this.householdId = householdId;
129	    }
130	
131	    public Integer getNamesakeCount() {
132	        return this.namesakeCount;
133	    }
134	
135	    public void setNamesakeCount(Integer namesakeCount) {
136	        this.namesakeCount = namesakeCount;
137	    }
138	
139	    public Boolean getBulkSignupWarning() {
140	        return this.bulkSignupWarning;
141	    }
142	
143	    public void setBulkSignupWarning(Boolean bulkSignupWarning) {
144	        this.bulkSignupWarning = bulkSignupWarning;
145	    }
146	
147	    public String getPostcode() {
148	        return this.postcode;
149	    }
150	
151	    public void setPostcode(String postcode) {
152	        this.postcode = postcode;
153	    }
154	
155	    /**
156	     * The owner's name formatted for display as {@code "LastName, FirstName"}.
157	     */
158	    @Transient
159	    public String getDisplayName() {
160	        return this.getLastName() + ", " + this.getFirstName();
161	    }
162	
163	    /**
164	     * The owner's initials: the upper-cased first letters of firstName and
165	     * lastName, dot-separated with a trailing dot (e.g. {@code "J.S."}).
166	     */
167	    @Transient
168	    public String getInitials() {
169	        return Character.toUpperCase(this.getFirstName().charAt(0)) + "."
170	            + Character.toUpperCase(this.getLastName().charAt(0)) + ".";
171	    }
172	
173	    /**
174	     * The owner's membership number, formatted {@code "<customerCode>-M<YY>"} where
175	     * YY is the last two digits of the registration date's year
176	     * (e.g. {@code "NSW-A1B2C3D4-M26"}). Derived from the owner's own fields; null when
177	     * either the customer code or registration date is absent.
178	     */
179	    @Transient
180	    public String getMembershipNumber() {
181	        if (this.customerCode == null || this.registrationDate == null) {
182	            return null;
183	        }
184	        return String.format("%s-M%02d", this.customerCode, this.registrationDate.getYear() % 100);
185	    }
186	
187	    /**
188	     * The owner's check digit: a single Luhn check digit (0-9) computed over the digits
189	     * contained in the {@code customerCode}, scanning right to left and doubling the
190	     * rightmost digit first; non-digit characters are ignored. Derived from the owner's
191	     * own fields; null when the customer code is absent.
192	     */
193	    @Transient
194	    public Integer getCheckDigit() {
195	        if (this.customerCode == null) {
196	            return null;
197	        }
198	        int sum = 0;
199	        boolean dbl = true;
200	        for (int i = this.customerCode.length() - 1; i >= 0; i--) {
201	            char c = this.customerCode.charAt(i);
202	            if (c < '0' || c > '9') {
203	                continue;
204	            }
205	            int d = c - '0';
206	            if (dbl) {
207	                d *= 2;
208	                if (d > 9) {
209	                    d -= 9;
210	                }
211	            }
212	            sum += d;
213	            dbl = !dbl;
214	        }
215	        return (10 - (sum % 10)) % 10;
216	    }
217	
218	    /**
219	     * The owner's membership level: a number from 1 to 3 assigned at creation. Starts
220	     * at 1, gains 1 when an email address is present, gains a further 1 when the owner
221	     * has no namesakes ({@code namesakeCount} is 0), and is capped at 3 (level 4 is
222	     * reserved for tenure). Derived from the owner's own fields.
223	     */
224	    @Transient
225	    public Integer getMembershipLevel() {
226	        int level = 1;
227	        boolean hasEmail = this.email != null && !this.email.isBlank();
228	        if (hasEmail) {
229	            level++;
230	        }
231	        boolean unique = this.namesakeCount != null && this.namesakeCount == 0;
232	        if (unique) {
233	            level++;
234	        }
235	        return Math.min(level, 3);
236	    }
237	
238	    /**
239	     * Fixed city-to-region lookup table. Any city not listed derives locality
240	     * {@code "UNKNOWN"}.
241	     */
242	    private static final Map<String, String> CITY_REGION = Map.of(
243	        "Sydney", "NSW",
244	        "Melbourne", "VIC",
245	        "Brisbane", "QLD");
246	
247	    /**
248	     * Region -> inclusive 4-digit postcode range {low, high}: NSW 2000-2099,
249	     * VIC 3000-3099, QLD 4000-4099. The single source of truth for the
250	     * postcode-to-region mapping, consulted by {@link #regionForPostcode(String)}
251	     * (used by locality derivation) and {@link #hasPostcodeRange(String)} (used by
252	     * postcode validation).
253	     */
254	    private static final Map<String, int[]> REGION_POSTCODE_RANGES = Map.of(
255	        "NSW", new int[] {2000, 2099},
256	        "VIC", new int[] {3000, 3099},
257	        "QLD", new int[] {4000, 4099});
258	
259	    /**
260	     * The owner's locality: the REGION component of the owner's region-and-hash identity.
261	     * Read off the {@code customerCode} prefix (the part before the first {@code '-'}) when
262	     * a customer code is present, otherwise derived straight from the postcode via
263	     * {@link #identityRegion(String)}. Either way this yields the region the customer code
264	     * was built from — NSW/VIC/QLD, or {@code "UNKNOWN"} when the postcode is absent or in
265	     * no known range. Derived from the owner's own fields.
266	     */
267	    @Transient
268	    public String getLocality() {
269	        if (this.customerCode != null) {
270	            int dash = this.customerCode.indexOf('-');
271	            if (dash > 0) {
272	                return this.customerCode.substring(0, dash);
273	            }
274	        }
275	        return identityRegion(this.postcode);
276	    }
277	
278	    /**
279	     * The REGION component of an owner's region-and-hash identity: the region derived from
280	     * the postcode via {@link #regionForPostcode(String)} (NSW/VIC/QLD), or
281	     * {@code "UNKNOWN"} when the postcode is absent or in no known range. The single source
282	     * of truth for the identity's region, so the {@code customerCode} prefix and the
283	     * {@link #getLocality() locality} cannot drift apart.
284	     */
285	    public static String identityRegion(String postcode) {
286	        String region = regionForPostcode(postcode);
287	        return region != null ? region : "UNKNOWN";
288	    }
289	
290	    /**
291	     * The canonical region for a city per the fixed city-to-region table
292	     * ({@code Sydney->NSW}, {@code Melbourne->VIC}, {@code Brisbane->QLD}), or
293	     * {@code "UNKNOWN"} when the city is not in the table. The single source of truth
294	     * for the city-to-region mapping, used as the city's region in postcode validation.
295	     */
296	    public static String regionForCity(String city) {
297	        return CITY_REGION.getOrDefault(city, "UNKNOWN");
298	    }
299	
300	    /**
301	     * The canonical region for a 4-digit postcode per the fixed range table
302	     * (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099), or {@code null} when the postcode
303	     * is absent, not a well-formed integer, or in no known range. Reads the shared
304	     * {@link #REGION_POSTCODE_RANGES} table; used by {@link #identityRegion(String)}
305	     * for the identity's region and by postcode validation to range-check a submitted
306	     * postcode against its city's region.
307	     */
308	    public static String regionForPostcode(String postcode) {
309	        if (postcode == null) {
310	            return null;
311	        }
312	        int value;
313	        try {
314	            value = Integer.parseInt(postcode.trim());
315	        } catch (NumberFormatException ex) {
316	            return null;
317	        }
318	        for (Map.Entry<String, int[]> entry : REGION_POSTCODE_RANGES.entrySet()) {
319	            int[] range = entry.getValue();
320	            if (value >= range[0] && value <= range[1]) {
321	                return entry.getKey();
322	            }
323	        }
324	        return null;
325	    }
326	
327	    /**
328	     * Whether the region is subject to postcode range validation, i.e. has a known
329	     * range in the shared {@link #REGION_POSTCODE_RANGES} table. A region with no range
330	     * (including {@code "UNKNOWN"}) accepts any well-formed postcode.
331	     */
332	    public static boolean hasPostcodeRange(String region) {
333	        return REGION_POSTCODE_RANGES.containsKey(region);
334	    }
335	
336	    /**
337	     * The owner's preferred contact channel: {@code "EMAIL"} when an email address is
338	     * present, otherwise {@code "PHONE"}. Derived from the owner's own fields.
339	     */
340	    @Transient
341	    public String getContactPreference() {
342	        boolean hasEmail = this.email != null && !this.email.isBlank();
343	        return hasEmail ? "EMAIL" : "PHONE";
344	    }
345	
346	    /**
347	     * The owner's identity key: the single value that duplicate detection is expressed
348	     * through, formed as {@code normalizedTelephone + "|" + (email or empty) + "|" +
349	     * (householdId or empty)}. The telephone and email are already stored in their
350	     * normalized forms (E.164 and lower-cased), and the household id is empty for a solo
351	     * owner. Two owners are duplicates only when their whole identity keys are equal, so
352	     * two members of the same household with different telephones have distinct keys.
353	     * Derived from the owner's own fields.
354	     */
355	    @Transient
356	    public String getIdentityKey() {
357	        return identityKey(this.telephone, this.email, this.householdId);
358	    }
359	
360	    /**
361	     * Composes an identity key from its already-normalized parts. The single place the
362	     * key's shape is defined, so the create-time duplicate check (which normalizes a
363	     * request's parts) and this entity's {@link #getIdentityKey()} cannot drift apart. A
364	     * null or blank part contributes an empty segment.
365	     */
366	    public static String identityKey(String normalizedTelephone, String normalizedEmail, String householdId) {
367	        return keyPart(normalizedTelephone) + "|" + keyPart(normalizedEmail) + "|" + keyPart(householdId);
368	    }
369	
370	    private static String keyPart(String value) {
371	        return (value == null || value.isBlank()) ? "" : value;
372	    }
373	
374	    protected Set<Pet> getPetsInternal() {
375	        if (this.pets == null) {
376	            this.pets = new HashSet<>();
377	        }
378	        return this.pets;
379	    }
380	
381	    protected void setPetsInternal(Set<Pet> pets) {
382	        this.pets = pets;
383	    }
384	
385	    public List<Pet> getPets() {
386	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
387	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
388	        return Collections.unmodifiableList(sortedPets);
389	    }
390	
391	    public void setPets(List<Pet> pets) {
392	        this.pets = new HashSet<>(pets);
393	    }
394	
395	    public void addPet(Pet pet) {
396	        getPetsInternal().add(pet);
397	        pet.setOwner(this);
398	    }
399	
400	    /**
401	     * Return the Pet with the given name, or null if none found for this Owner.
402	     *
403	     * @param name to test
404	     * @return true if pet name is already in use
405	     */
406	    public Pet getPet(String name) {
407	        return getPet(name, false);
408	    }
409	
410	    /**
411	     * Return the Pet with the given name, or null if none found for this Owner.
412	     *
413	     * @param name to test
414	     * @return true if pet name is already in use
415	     */
416	    public Pet getPet(String name, boolean ignoreNew) {
417	        name = name.toLowerCase();
418	        for (Pet pet : getPetsInternal()) {
419	            if (!ignoreNew || !pet.isNew()) {
420	                String compName = pet.getName();
421	                compName = compName.toLowerCase();
422	                if (compName.equals(name)) {
423	                    return pet;
424	                }
425	            }
426	        }
427	        return null;
428	    }
429	
430	    public Pet getPet(Integer petId) {
431	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
432	    }
433	
434	    @Override
435	    public String toString() {
436	        return new ToStringCreator(this)
437	
438	            .append("id", this.getId())
439	            .append("new", this.isNew())
440	            .append("lastName", this.getLastName())
441	            .append("firstName", this.getFirstName())
442	            .append("address", this.address)
443	            .append("city", this.city)
444	            .append("telephone", this.telephone)
445	            .append("email", this.email)
446	            .toString();
447	    }
448	}
